261	    pub(crate) fn all_rank_load_bundles(
262	        &self,
263	        moe_topo: crate::Glm52MoeTopo,
264	        native_mtp: bool,
265	    ) -> Result<Vec<Glm52RankLoadBundle>> {
266	        (0..moe_topo.device_count())
267	            .map(|rank| self.rank_load_bundle(rank, moe_topo, native_mtp))
268	            .collect()
269	    }
270	
271	    /// Shard file holding `name` (TP slice second-pass loads resolve every
272	    /// expert's tensors, not just this rank's 32-expert bundle).
273	    pub(crate) fn shard_for(&self, name: &str) -> Result<&str> {
274	        self.weight_map
275	            .get(name)
276	            .map(String::as_str)
277	            .with_context(|| format!("GLM5.2 safetensors index missing tensor {name}"))
278	    }
279	
280	    fn rank_load_bundle(
281	        &self,
282	        rank: usize,
283	        moe_topo: crate::Glm52MoeTopo,
284	        native_mtp: bool,
285	    ) -> Result<Glm52RankLoadBundle> {
286	        let names = self.rank_resident_tensor_names(rank, moe_topo, native_mtp)?;
287	        let mut by_shard: BTreeMap<String, Vec<Glm52TensorLoadSpec>> = BTreeMap::new();
288	        for name in names {
289	            let shard = self
290	                .weight_map
291	                .get(&name)
292	                .with_context(|| format!("GLM5.2 safetensors index missing tensor {name}"))?;
293	            by_shard
294	                .entry(shard.clone())
295	                .or_default()
296	                .push(Glm52TensorLoadSpec {
297	                    name,
298	                    shard: shard.clone(),
299	                });
300	        }
301	        let tensor_count = by_shard.values().map(Vec::len).sum();
302	        // Tensor-replicated topologies carry no expert tensors in the
303	        // resident plan; their bundles get an empty range.
304	        let expert_range = if moe_topo.uses_ep_expert_bundles() {
305	            let local = moe_topo.ep_local_experts();
306	            rank * local..(rank + 1) * local
307	        } else {
308	            0..0
309	        };
310	        Ok(Glm52RankLoadBundle {
311	            plan: Glm52RankWeightPlan {
312	                rank,
313	                expert_range,
314	                tensor_count,
315	                native_mtp,
316	            },
317	            shards: by_shard
318	                .into_iter()
319	                .map(|(shard, tensors)| Glm52ShardLoadPlan { shard, tensors })
320	                .collect(),
321	        })
322	    }
323	
324	    /// Full checkpoint coverage, including the MTP accuracy-oracle layer.
325	    /// This is a manifest invariant only: resident load plans below
326	    /// deliberately omit tensors that the serving model never consumes.
327	    fn rank_tensor_names(&self, rank: usize) -> Result<Vec<String>> {
328	        ensure!(
329	            rank < GLM52_EP_RANKS,
330	            "GLM5.2 rank must be in 0..{GLM52_EP_RANKS}, got {rank}"
331	        );
332	        let mut names = Vec::new();
333	        self.push_checkpoint_non_expert_names(&mut names);
334	        let expert_start = rank * GLM52_LOCAL_EXPERTS;
335	        let expert_range = expert_start..expert_start + GLM52_LOCAL_EXPERTS;
336	        for layer_idx in GLM52_DENSE_LAYERS..=GLM52_MTP_LAYER {
337	            push_routed_experts(&mut names, layer_idx, expert_range.clone());
338	        }
339	        Ok(names)
340	    }
341	
342	    /// Tensors that must become GPU-resident for one serving rank. MTP layer
343	    /// 78 enters the EP plan only when native MTP is enabled. TP4 gets all
344	    /// routed + shared experts from `load_tp_slice_layer`, so its first pass
345	    /// loads routers but not duplicate full shared-expert projections.
346	    fn rank_resident_tensor_names(
347	        &self,
348	        rank: usize,
349	        moe_topo: crate::Glm52MoeTopo,
350	        native_mtp: bool,
351	    ) -> Result<Vec<String>> {
352	        ensure!(
353	            rank < moe_topo.device_count(),
354	            "GLM5.2 rank must be in 0..{}, got {rank}",
355	            moe_topo.device_count()
356	        );
357	        let mut names = Vec::new();
358	        self.push_resident_non_expert_names(&mut names, moe_topo.uses_ep_expert_bundles());
359	        if moe_topo.uses_ep_expert_bundles() {
360	            let local = moe_topo.ep_local_experts();
361	            let expert_range = rank * local..(rank + 1) * local;
362	            for layer_idx in GLM52_DENSE_LAYERS..GLM52_LAYERS {
363	                push_routed_experts(&mut names, layer_idx, expert_range.clone());
364	            }
365	            if native_mtp {
366	                self.push_mtp_non_expert_names(&mut names, true);
367	                push_routed_experts(&mut names, GLM52_MTP_LAYER, expert_range);
368	            }
369	        } else {
370	            if native_mtp {
371	                self.push_mtp_non_expert_names(&mut names, false);
372	            }
373	        }
374	        Ok(names)
375	    }
376	
377	    fn push_resident_non_expert_names(
378	        &self,
379	        names: &mut Vec<String>,
380	        include_shared_experts: bool,
381	    ) {
382	        names.push("model.embed_tokens.weight".to_owned());
383	        names.push("model.norm.weight".to_owned());
384	        names.push("lm_head.weight".to_owned());
385	
386	        for layer_idx in 0..GLM52_LAYERS {
387	            self.push_attention_names(names, layer_idx);
388	            if layer_idx < GLM52_DENSE_LAYERS {
389	                push_dense_mlp(names, layer_idx);
390	            } else {
391	                push_moe_non_expert(names, layer_idx, include_shared_experts);
392	            }
393	        }
394	    }
395	
396	    fn push_checkpoint_non_expert_names(&self, names: &mut Vec<String>) {
397	        self.push_resident_non_expert_names(names, true);
398	        self.push_mtp_non_expert_names(names, true);
399	    }
400	
401	    fn push_mtp_non_expert_names(&self, names: &mut Vec<String>, include_shared_experts: bool) {
402	        names.push(format!("model.layers.{GLM52_MTP_LAYER}.enorm.weight"));
403	        names.push(format!("model.layers.{GLM52_MTP_LAYER}.hnorm.weight"));
404	        names.push(format!("model.layers.{GLM52_MTP_LAYER}.eh_proj.weight"));
405	        names.push(format!(
406	            "model.layers.{GLM52_MTP_LAYER}.shared_head.norm.weight"
407	        ));
408	        self.push_attention_names(names, GLM52_MTP_LAYER);
409	        push_moe_non_expert(names, GLM52_MTP_LAYER, include_shared_experts);
410	    }
411	
412	    fn push_attention_names(&self, names: &mut Vec<String>, layer_idx: usize) {
413	        let prefix = format!("model.layers.{layer_idx}");
414	        names.push(format!("{prefix}.input_layernorm.weight"));
415	        push_fp8(names, &format!("{prefix}.self_attn.q_a_proj"));
416	        names.push(format!("{prefix}.self_attn.q_a_layernorm.weight"));
417	        push_fp8(names, &format!("{prefix}.self_attn.q_b_proj"));
418	        push_fp8(names, &format!("{prefix}.self_attn.kv_a_proj_with_mqa"));
419	        names.push(format!("{prefix}.self_attn.kv_a_layernorm.weight"));
420	        push_fp8(names, &format!("{prefix}.self_attn.kv_b_proj"));
421	        push_fp8(names, &format!("{prefix}.self_attn.o_proj"));
422	        names.push(format!("{prefix}.post_attention_layernorm.weight"));
423	
424	        let indexer = format!("{prefix}.self_attn.indexer");
425	        if self
426	            .weight_map
427	            .contains_key(&format!("{indexer}.k_norm.weight"))
428	        {
429	            names.push(format!("{indexer}.k_norm.weight"));
430	            names.push(format!("{indexer}.k_norm.bias"));
431	            names.push(format!("{indexer}.weights_proj.weight"));
432	            push_fp8(names, &format!("{indexer}.wk"));
433	            push_fp8(names, &format!("{indexer}.wq_b"));
434	        }
435	    }
436	
437	    fn validate_rank_coverage(&self) -> Result<()> {
438	        let mut generated = BTreeSet::new();
439	        for rank in 0..GLM52_EP_RANKS {
440	            for name in self.rank_tensor_names(rank)? {
441	                generated.insert(name);
442	            }
443	        }
444	        let checkpoint = self.weight_map.keys().cloned().collect::<BTreeSet<_>>();
445	        let missing = checkpoint
446	            .difference(&generated)
447	            .take(5)
448	            .cloned()
449	            .collect::<Vec<_>>();
450	        let extra = generated
451	            .difference(&checkpoint)
452	            .take(5)
453	            .cloned()
454	            .collect::<Vec<_>>();
455	        ensure!(
456	            missing.is_empty() && extra.is_empty(),
457	            "GLM5.2 rank load plan does not exactly cover checkpoint tensors: missing_sample={missing:?}, extra_sample={extra:?}, checkpoint={}, generated={}",
458	            checkpoint.len(),
459	            generated.len()
460	        );
461	        Ok(())
462	    }
463	}
